package com.ekayn.api.api;
import com.ekayn.api.api.ApiModels.*; import com.ekayn.api.model.*; import com.ekayn.api.repo.*; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/me") @RequiredArgsConstructor
public class ProfileController {
 private final UserRepository users; private final AddressRepository addresses; private final PasswordEncoder encoder;
 @GetMapping public ProfileResponse me(@AuthenticationPrincipal User u){return profile(u);}
 @PatchMapping public ProfileResponse update(@AuthenticationPrincipal User u,@Valid @RequestBody Profile p){u.setFirstName(p.firstName());u.setLastName(p.lastName());u.setPhone(p.phone());users.save(u);return profile(u);}
 @PatchMapping("/password") public void password(@AuthenticationPrincipal User u,@Valid @RequestBody PasswordChange p){if(!encoder.matches(p.currentPassword(),u.getPasswordHash()))throw new IllegalArgumentException("Mot de passe actuel invalide.");if(!p.newPassword().equals(p.confirmation()))throw new IllegalArgumentException("Les mots de passe ne correspondent pas.");u.setPasswordHash(encoder.encode(p.newPassword()));u.setSessionVersion(u.getSessionVersion()+1);users.save(u);}
 @GetMapping("/addresses") public List<AddressResponse> addresses(@AuthenticationPrincipal User u){return addresses.findByUserId(u.getId()).stream().map(this::address).toList();}
 @PostMapping("/addresses") public AddressResponse add(@AuthenticationPrincipal User u,@Valid @RequestBody AddressInput p){return address(saveAddress(u,null,p));}
 @PatchMapping("/addresses/{id}") public AddressResponse edit(@AuthenticationPrincipal User u,@PathVariable UUID id,@Valid @RequestBody AddressInput p){return address(saveAddress(u,id,p));}
 private Address saveAddress(User u,UUID id,AddressInput p){Address a=id==null?new Address():addresses.findByIdAndUserId(id,u.getId()).orElseThrow(()->new NoSuchElementException("Adresse introuvable."));a.setUser(u);a.setLabel(p.label());a.setLine1(p.line1());a.setLine2(p.line2());a.setCity(p.city());a.setPostalCode(p.postalCode());a.setCountry(p.country());if(p.defaultAddress())addresses.findByUserId(u.getId()).forEach(x->{x.setDefaultAddress(false);addresses.save(x);});a.setDefaultAddress(p.defaultAddress()||addresses.findByUserId(u.getId()).isEmpty());return addresses.save(a);}
 @PostMapping("/addresses/{id}/default") public AddressResponse makeDefault(@AuthenticationPrincipal User u,@PathVariable UUID id){Address a=addresses.findByIdAndUserId(id,u.getId()).orElseThrow(()->new NoSuchElementException("Adresse introuvable."));addresses.findByUserId(u.getId()).forEach(x->{x.setDefaultAddress(false);addresses.save(x);});a.setDefaultAddress(true);return address(addresses.save(a));}
 @DeleteMapping("/addresses/{id}") public void remove(@AuthenticationPrincipal User u,@PathVariable UUID id){addresses.delete(addresses.findByIdAndUserId(id,u.getId()).orElseThrow(()->new NoSuchElementException("Adresse introuvable.")));}
 @DeleteMapping public void deleteAccount(@AuthenticationPrincipal User u,@Valid @RequestBody AccountDeletion p){if(!p.confirmed()||!encoder.matches(p.currentPassword(),u.getPasswordHash()))throw new IllegalArgumentException("Réauthentification ou confirmation invalide.");addresses.deleteAll(addresses.findByUserId(u.getId()));u.setEmail("deleted+"+u.getId()+"@ekayn.invalid");u.setFirstName("Compte");u.setLastName("supprimé");u.setPhone(null);u.setPasswordHash(encoder.encode(UUID.randomUUID().toString()));u.setSessionVersion(u.getSessionVersion()+1);users.save(u);}
 private ProfileResponse profile(User u){return new ProfileResponse(u.getId(),u.getEmail(),u.getFirstName(),u.getLastName(),u.getPhone(),u.isEmailVerified(),u.getRole().name());}
 private AddressResponse address(Address a){return new AddressResponse(a.getId(),a.getLabel(),a.getLine1(),a.getLine2(),a.getCity(),a.getPostalCode(),a.getCountry(),a.isDefaultAddress());}
}
